pub tracked struct NrLogAppendExecDataGhost<DT: Dispatch> {
    pub                      
     local_updates: Tracked::<Map<ReqId, UnboundedLog::local_updates<DT>>>,
    pub                      
     ghost_replica: Tracked<UnboundedLog::replicas<DT>>,
    pub                      
