    assert!(!check_changed(r#"
verus! {
    #[inductive(reader_finish)]
    fn reader_finish_inductive(pre: int, post: int, node_id: nat) {
    }
}
"#));

    assert!(!check_changed(r#"
verus! {
    #[inductive(reader_abort)]
    fn reader_finish_inductive(pre: int, post: int, node_id: int) {
    }
}
"#));
}

